ga0k(){return"<def>\ubc29\uc5b4\ub825</def>\uc774 \ub192\uc544\uc838 \ubc1b\ub294 \ud53c\ud574\uac00 \uc904\uc5b4\uc694."},
ga0l(){return"\ubc29\uc5b4\ub825 \uc99d\uac00\ub294 \uc9c0\uc18d\ub418\ub294 \ub3d9\uc548 <def>\ubc29\uc5b4\ub825</def>\uc744 \uc77c\uc815 \ube44\uc728 \ub192\uc5ec\uc694. Ovaling\uc774 \ubc1b\ub294 \ubaa8\ub4e0 \ud0c0\uaca9\uc758 \ud53c\ud574\uac00 \uc791\uc544\uc838\uc694."},
ga0O(){return"\uc790\uc2e0\uc758 \ud134\uc774 \uc2dc\uc791\ub420 \ub54c\ub9c8\ub2e4 \ud68c\ubcf5\ud574\uc694."},
ga0P(){return"\ud6a8\uacfc\uac00 \ub05d\ub0a0 \ub54c\uae4c\uc9c0 \uc790\uc2e0\uc758 \ud134\uc774 \uc2dc\uc791\ub420 \ub54c\ub9c8\ub2e4 Ovaling\uc774 \ucd5c\ub300 <hp>\uccb4\ub825</hp>\uc758 \uc77c\ubd80\ub97c \ud68c\ubcf5\ud574\uc694."},
ga0U(){return"<hp>\uccb4\ub825</hp>\ubcf4\ub2e4 \uba3c\uc800 \ud53c\ud574\ub97c \ud761\uc218\ud574\uc694."},
ga0V(){return"\ubcf4\ud638\ub9c9\uc740 \ucd5c\ub300 <hp>\uccb4\ub825</hp>\uc758 \uc77c\ubd80\ub85c \ub9cc\ub4e0 \uc644\ucda9\ub9c9\uc774\uc5d0\uc694. \ud53c\ud574\ub294 \uba3c\uc800 \ubcf4\ud638\ub9c9\uc5d0 \ub4e4\uc5b4\uac00\uace0 \uadf8\ub2e4\uc74c <hp>\uccb4\ub825</hp>\uc5d0 \ub4e4\uc5b4\uac00\uc694. \ubcf4\ud638\ub9c9\uc740 \uc9c0\uc18d \uc2dc\uac04\uc774 \uc5c6\uace0 \uc18c\uc9c4\ub420 \ub54c\uae4c\uc9c0 \ub0a8\uc544\uc694. \uc870\uae08\uc774\ub77c\ub3c4 \ub0a8\uc544 \uc788\ub294 \ub3d9\uc548\uc5d0\ub294 \ubc1b\ub294 \ubaa8\ub4e0 \ud53c\ud574\ub97c \ucd5c\uc18c 5% \uc904\uc5ec \uc8fc\uace0, \uc774\ub54c \ud53c\ud574 \uac10\uc18c \uc544\uc774\ucf58\uc774 \ud45c\uc2dc\ub3fc\uc694."},
ga0u(){return"\uc989\uc2dc <hp>\uccb4\ub825</hp>\uc744 \ud68c\ubcf5\ud574\uc694."},
ga0v(){return"\ud68c\ubcf5\uc740 \ub300\uc0c1\uc758 \ucd5c\ub300 <hp>\uccb4\ub825</hp> \uc77c\ubd80\ub97c \uc989\uc2dc \ub418\ub3cc\ub824\uc694. <hp>\uccb4\ub825</hp>\uc740 \ucd5c\ub300\uce58\ub97c \ub118\uc9c0 \uc54a\uc544\uc694."},
ga0C(){return"\uc785\ud78c \ud53c\ud574\uc758 \uc77c\ubd80\ub9cc\ud07c \ud68c\ubcf5\ud574\uc694."},
