ga0E(){return"\ud134 \uac8c\uc774\uc9c0 \uc77c\ubd80\ub97c \ube44\uc6cc\uc694."},
ga0F(){return"\ud134 \uac8c\uc774\uc9c0 \uac10\uc18c\ub294 \ub300\uc0c1\uc758 \ud134 \uac8c\uc774\uc9c0\ub97c \uc77c\uc815 \ube44\uc728 \uae4e\uc544 \ub2e4\uc74c \ud134\uc774 \ub2a6\uac8c \uc640\uc694."},
ga0G(){return"\ud134 \uac8c\uc774\uc9c0 \uc77c\ubd80\ub97c \ucc44\uc6cc\uc694."},
ga0H(){return"\ud134 \uac8c\uc774\uc9c0 \uc99d\uac00\ub294 \ub300\uc0c1\uc758 \ud134 \uac8c\uc774\uc9c0\ub97c \uc77c\uc815 \ube44\uc728 \ucc44\uc6cc \ub2e4\uc74c \ud134\uc774 \ube68\ub9ac \uc640\uc694."},
ga0a(){return"\ubaa8\ub4e0 \uc57d\ud654 \ud6a8\uacfc\ub97c \uc81c\uac70\ud574\uc694."},
ga0b(){return"\uc815\ud654\ub294 \ub300\uc0c1\uc758 \ubaa8\ub4e0 \uc57d\ud654 \ud6a8\uacfc\ub97c \ud55c \ubc88\uc5d0 \uc81c\uac70\ud574\uc694. \uc608\ub97c \ub4e4\uc5b4 \ub3c5, \uae30\uc808, <atk>\uacf5\uaca9\ub825</atk>, <def>\ubc29\uc5b4\ub825</def>, <spd>\uc18d\ub3c4</spd> \uac10\uc18c\uac00 \ubaa8\ub450 \uc0ac\ub77c\uc838\uc694. \uac15\ud654 \ud6a8\uacfc\uc640 \ubcf4\ud638\ub9c9\uc740 \ub0a8\uc544\uc694."},
ga0Q(){return"\uc4f0\ub7ec\uc9c4 \uc544\uad70\uc744 \ub418\uc0b4\ub824\uc694."},
ga0R(){return"\ubd80\ud65c\uc740 \uc4f0\ub7ec\uc9c4 Ovaling\uc744 <hp>\uccb4\ub825</hp> \uc77c\ubd80\uc640 \ud568\uaed8 \uc804\ud22c\ub85c \ub418\ub3cc\ub824\uc694. \uac01 Ovaling\uc740 \uc804\ud22c\ub9c8\ub2e4 \ud55c \ubc88\ub9cc \ubd80\ud65c\ud560 \uc218 \uc788\uc5b4\uc694."},
gZw(){return"<fx:poison>\ub3c5</fx>\uc5d0 \uba74\uc5ed."},
gZx(){return"\uc5ec\uc655\uc758 <fx:poison>\ub3c5</fx>\uc740 \ucd5c\ub300 3\ubc88 \uc911\ucca9\ub3fc\uc694."},
gZv(){return"\ub3c5\uc758 \ud53c: \uc5ec\uc655\uc744 \uc9c1\uc811 \uacf5\uaca9\ud558\uba74 25% \ud655\ub960\ub85c <fx:poison>\uc911\ub3c5</fx>\ub3fc\uc694 (2\ud134 \ub3d9\uc548 \ud134\ub9c8\ub2e4 \ucd5c\ub300 <hp>\uccb4\ub825</hp>\uc758 3%)."},
Zm(a){return"\uac11\uc637: \uce58\uba85\ud0c0\ub9cc \ud53c\ud574\ub97c \uc8fc\uace0 \ub098\uba38\uc9c0\ub294 \ubaa8\ub450 \ud295\uaca8 \ub098\uac00\uc694. \uc774 \ubcf4\uc2a4\ub97c \uc0c1\ub300\ub85c\ub294 <crit>\uce58\uba85\ud0c0 \ud655\ub960</crit>\uc774 "+a+"%p \ub0ae\uc544\uc9c0\uba70, \ud655\uc815 \uce58\uba85\ud0c0\ub294 \ud56d\uc0c1 \uc801\uc911\ud574\uc694."},
ZB(a){return"\ud314 \uc655\uad00: \ubaa8\ub4e0 \ud314\uc774 \uacf5\uaca9\ud560 \uc218 \uc788\uc5b4\uc694. \ubca0\uc5b4 \ub0b4\uba74 \uc5ec\uc655\uc774 \uc57d\ud574\uc838\uc694. \uc5ec\uc655\uc758 \ud134\uc774 \ub05d\ub0a0 \ub54c\ub9c8\ub2e4 \uac01\uac01 "+a+"% \ud655\ub960\ub85c \uacf5\uaca9\ud574\uc694."},
ZC(a){return"\uc7ac\uc0dd: <hp>\uccb4\ub825</hp>\uc774 \ucc98\uc74c\uc73c\ub85c "+a+"% \uc544\ub798\ub85c \ub5a8\uc5b4\uc9c0\uba74 \ud314 \ud558\ub098\uac00 \ub2e4\uc2dc \uc790\ub77c\uc694."},
gwy(){return"\uc11d\ud654\uc758 \ub208\ube5b: \uac00\uc7a5 \uac15\ud55c Ovaling\uc744 \ub208\ube5b\uc73c\ub85c <fx:petrify>\ub3cc</fx>\ub85c \ub9cc\ub4e4\uc5b4\uc694. <fx:heal>\ud68c\ubcf5</fx>\ud558\uac70\ub098 <fx:cleanse>\uc815\ud654</fx>\ud558\uba74 \ub2e4\uc2dc \ud480\ub824\ub098\uc694."},
