Mw(a,b,c){return a+" "+b+" \ub3d9\uc548 [!\ud68c\ubcf5 \uac10\uc18c!]\ub97c \uc918\uc694: \ud68c\ubcf5\ub7c9\uc774 "+c+"% \uc904\uc5b4\uc694."},
Ms(a){return"[!\ub3c5 \ubc29\ucd9c!]: "+a+" \uad34\ub86d\ud788\ub358 \ubaa8\ub4e0 \ub3c5\uc774 \ub0a8\uc740 \ud53c\ud574\ub97c \ud55c\uaebc\ubc88\uc5d0 \uc785\ud788\uace0 \uc0ac\ub77c\uc838\uc694."},
ga0s(){return"\ub300\uc0c1\uc774 \ubc1b\ub294 \ud68c\ubcf5\uc774 \uc904\uc5b4\uc694."},
ga0t(){return"\uc9c0\uc18d\ub418\ub294 \ub3d9\uc548 \ub300\uc0c1\uc774 \ubc1b\ub294 \ubaa8\ub4e0 \ud68c\ubcf5\uc774 \uc2a4\ud0ac \uac12\ub9cc\ud07c \uc904\uc5b4\uc694. \ud761\ud608\uacfc \uc9c0\uc18d \ud68c\ubcf5\ub3c4 \ud3ec\ud568\uc774\uc5d0\uc694. \uc815\ud654\ub85c \uc5c6\uc568 \uc218 \uc788\uc5b4\uc694."},
ga0m(){return"\ub3c5\uc774 \ubaa8\ub4e0 \ud53c\ud574\ub97c \ud55c\uaebc\ubc88\uc5d0 \uc785\ud600\uc694."},
