Md(a){return"\uce58\uba85\ud0c0\uac00 \ub098\uc62c \ub54c\ub9c8\ub2e4 \ud55c \ubc88 \ub354 \uacf5\uaca9\ud574\uc694 (\ucd5c\ub300 "+a+"\ud68c \ucd94\uac00)."},
zf(a){return"\uce58\uba85\ud0c0 \uc5f0\uc1c4 +"+a},
VR(a){return"\uc774 Ovaling\uc758 <fx:heal>\ud68c\ubcf5</fx>\uacfc <fx:shield>\ubcf4\ud638\ub9c9</fx>\uc774 "+a+"% \uac15\ud574\uc838\uc694."},
Wp(a){return"\ubaa8\ub4e0 \uc804\ud22c\uac00 \uc2dc\uc791\ub420 \ub54c \ud300 \uc804\uccb4\uac00 \ucd5c\ub300 <hp>\uccb4\ub825</hp>\uc758 "+a+"% <fx:shield>\ubcf4\ud638\ub9c9</fx>\uc744 \ubc1b\uc544\uc694."},
Vn(a){return"\uc790\uc2e0\uc758 \uce58\uba85\ud0c0\uac00 \ub300\uc0c1\uc744 2\ud134 \ub3d9\uc548 <fx:bleed>\ucd9c\ud608</fx>\uc2dc\ucf1c\uc694 (\ud134\ub9c8\ub2e4 \uc790\uc2e0 <atk>\uacf5\uaca9\ub825</atk>\uc758 "+a+"% \ud53c\ud574)."},
VK(a){return"<hp>\uccb4\ub825</hp>\uc774 30% \ubbf8\ub9cc\uc778 \ub300\uc0c1\uc5d0\uac8c \ud53c\ud574 +"+a+"%."},
