V9(a){return"\uc0b4\uc544 \uc788\ub294 \ub3d9\uc548 \uc5ec\ub7ec \ub300\uc0c1\uc744 \ub178\ub9ac\ub294 \uacf5\uaca9\uc5d0 \ud300\uc774 <fx:damage_reduction>\ubc1b\ub294 \ud53c\ud574\uac00 "+a+"% \uc904\uc5b4\uc694</fx>."},
VL(a){return"\ud300 Ovaling\uc758 <hp>\uccb4\ub825</hp>\uc774 \ucc98\uc74c\uc73c\ub85c 50% \uc544\ub798\ub85c \ub5a8\uc5b4\uc9c0\uba74 \uc989\uc2dc \ucd5c\ub300 <hp>\uccb4\ub825</hp>\uc758 "+a+"%\ub97c <fx:heal>\ud68c\ubcf5</fx>\ud574\uc694. Ovaling\ub9c8\ub2e4 \uc804\ud22c\ub2f9 1\ubc88."},
W0(a){return"\uc0b4\uc544 \uc788\ub294 \ub3d9\uc548 \uac01 \uc801\uc758 \uccab \uacf5\uaca9\uc5d0 \ud300\uc774 <fx:damage_reduction>\ubc1b\ub294 \ud53c\ud574\uac00 "+a+"% \uc904\uc5b4\uc694</fx>. \uc790\uc2e0\uc758 3\ubc88\uc9f8 \ud134\ub9c8\ub2e4 \ub2e4\uc2dc \uc2dc\uc791\ub3fc\uc694."},
W2(a){var s=""+a
return"\uc790\uc2e0\uc758 \ud134\uc774 \uc2dc\uc791\ub420 \ub54c \ubc88\uac08\uc544 \ubc1c\ub3d9\ud574\uc694: \ud300 \uc804\uccb4\uac00 1\ud134 \ub3d9\uc548 [[<atk>\uacf5\uaca9\ub825</atk> +"+s+"%]], \ub2e4\uc74c\uc5d0\ub294 1\ud134 \ub3d9\uc548 <fx:damage_reduction>\ubc1b\ub294 \ud53c\ud574 "+s+"% \uac10\uc18c</fx>."},
Ve(a){return"\ud300\uc758 Ovaling\uc774 <hp>\uccb4\ub825</hp>\uc758 15% \uc774\uc0c1\uc778 \uacf5\uaca9\uc744 \ubc84\ud2f0\uba74 \uc989\uc2dc <hp>\uccb4\ub825</hp>\uc758 "+a+"% <fx:shield>\ubcf4\ud638\ub9c9</fx>\uc744 \uc5bb\uc5b4\uc694."},
Vw(a){return"\uc804\ud22c\uc640 \uc0c8 \uc6e8\uc774\ube0c\uac00 \uc2dc\uc791\ub420 \ub54c \uc774\ubbf8 [[\ud134 \uac8c\uc774\uc9c0 "+a+"%]]\ub97c \uac00\uc9c0\uace0 \uc788\uc5b4\uc694."},
Wf(a){return"\ud56d\uc0c1 [[<spd>\uc18d\ub3c4</spd> +"+a+"%]]."},
VX(a){return"<hp>\uccb4\ub825</hp>\uc774 "+a+"%\ubcf4\ub2e4 \ub9ce\uc740 \ub3d9\uc548 \uc801\uc758 \ub2e8\uc77c \uacf5\uaca9\uc774 <fx:taunt>\ub3c4\ubc1c</fx>\ucc98\ub7fc \uc790\uc2e0\uc5d0\uac8c \uc640\uc694. \uadf8\ub3d9\uc548 <fx:damage_reduction>\ubc1b\ub294 \ud53c\ud574\uac00 20% \uc904\uc5b4\uc694</fx>."},
